import { guideLesson } from './define.ts';
import type { Lesson } from './types.ts';
const P = (slug: string, title: string, prerequisites: string[], objectives: string[], sections: Lesson['sections'], question: string, options: string[], answer: number, explanation: string): Lesson => guideLesson('plat', slug, { title, description: objectives.join(' · '), minutes: 45, prerequisites, objectives, sections, quiz: { question, options, answer, explanation } });
export const platinumLessons: Lesson[] = [
P('segtree-ext','Árboles de segmentos: buscar y combinar estados',['usaco-gold-purs'],['Descender por el árbol para encontrar una posición','Diseñar agregados asociativos enriquecidos'],[
{title:'El resumen decide qué puedes preguntar',body:'Un árbol de segmentos no está limitado a almacenar sumas. Cada nodo resume un intervalo y su padre combina los resúmenes de dos mitades. La operación debe ser asociativa: combinar tres intervalos consecutivos debe producir el mismo resultado independientemente de cómo se agrupen. No necesita ser conmutativa; concatenar cadenas o componer funciones depende del orden y exige respetar siempre izquierda antes que derecha.'},
{title:'Encontrar la primera capacidad suficiente',body:'Hay habitaciones con capacidades [2,7,1,5] y llega un grupo de cuatro. Guardamos máximos por intervalo. El máximo de la mitad izquierda es siete, así que la primera habitación adecuada está allí; el primer elemento no alcanza, por lo que elegimos índice uno. Restamos cuatro y su capacidad pasa a tres. En cada descenso conservamos el invariante de que el intervalo actual contiene una respuesta y descartamos la mitad izquierda solo cuando su máximo es menor que la petición.'},
{title:'Más información en un solo nodo',body:'Para máxima suma de subarreglo, almacena cuatro datos: suma total, mejor prefijo, mejor sufijo y mejor subarreglo. Al unir A y B, la mejor respuesta es max(A.mejor,B.mejor,A.sufijo+B.prefijo); el prefijo es max(A.prefijo,A.suma+B.prefijo), y el sufijo se calcula simétricamente. Define de antemano si el subarreglo vacío está permitido. Para funciones afines, combina coeficientes en el orden de aplicación, pues aplicar 2x+1 y después 3x produce 6x+3, no 6x+1.'},
{title:'Costo y pruebas de frontera',body:'Construir cuesta O(n); actualizar, consultar un rango o descender por una búsqueda válida cuesta O(log n), suponiendo resúmenes de tamaño constante. Para buscar el k-ésimo elemento con sumas de frecuencias, las frecuencias deben ser no negativas: así los prefijos son monótonos. No hagas búsqueda binaria con una consulta completa en cada paso si puedes descender directamente. Practica capacidades [2,7,1,5] con grupos [4,3,6]: seleccionas índices uno, uno y ninguno. Prueba también arreglos con todos los valores negativos para detectar una inicialización incorrecta del máximo subarreglo.'}
],'Al buscar la primera capacidad ≥4 en [2,7,1,5], ¿qué índice desde cero obtienes?',['0','1','2','3'],1,'El máximo de la mitad izquierda permite entrar allí; 2 no alcanza y 7 sí, por lo que la primera posición es 1.'),
P('range-sweep','Consultas por barrido y eventos ordenados',['usaco-gold-purs','usaco-silver-sorting-custom'],['Convertir una dimensión en tiempo de procesamiento','Definir desempates entre eventos'],[
{title:'Una coordenada se vuelve el reloj',body:'Muchos problemas bidimensionales pueden procesarse ordenando una coordenada y manteniendo una estructura sobre la otra. La estructura representa exactamente los objetos activos en la posición actual del barrido. Esta reducción requiere formular qué significa activo, cuándo entra un objeto y cuándo sale. Si conoces todas las consultas de antemano, puedes reorganizarlas y después devolver respuestas en su orden original; eso es procesamiento fuera de línea.'},
{title:'Contar cruces de segmentos',body:'Considera segmentos verticales en x=2 desde y=1 hasta y=5, y en x=6 desde y=0 hasta y=3. Un segmento horizontal desde x=1 hasta x=7 a altura y=2 cruza ambos: respuesta dos. Barre por y. Al inicio de un vertical agrega uno a su x en Fenwick, al final resta uno y, para cada horizontal, consulta la suma sobre su intervalo x. Compresión de coordenadas permite manejar posiciones enormes conservando el orden.'},
{title:'La igualdad entre eventos importa',body:'Si los segmentos incluyen sus extremos, para una misma altura procesa primero entradas, después consultas y finalmente salidas. Así un horizontal que toca el extremo de un vertical lo cuenta. Si la definición excluye extremos, cambia el desempate correspondiente. El invariante después de preparar una consulta es que Fenwick contiene precisamente los verticales que intersectan esa altura. Una técnica relacionada ordena puntos por x para contestar cuántos cumplen simultáneamente x≤X e y≤Y.'},
{title:'Costo y límites del modelo',body:'Con n segmentos y consultas, ordenar cuesta O(n log n) y cada evento O(log n), con O(n) memoria. El modelo de cruces descrito cuenta pares vertical–horizontal; no resuelve automáticamente superposiciones entre dos horizontales ni todos los problemas de segmentos arbitrarios. Practica agregando un horizontal a altura tres: el vertical en x=6 debe contarse si sus extremos son inclusivos. Después adapta a consultas de rectángulos restando cuatro prefijos y explica por qué cada punto interior contribuye exactamente una vez.'}
],'Con extremos inclusivos y eventos de igual altura, ¿qué orden es correcto?',['Salida, consulta, entrada','Consulta, entrada, salida','Entrada, consulta, salida'],2,'La entrada debe estar activa durante la consulta y la salida debe retirarse después, para incluir ambos extremos.'),
P('RURQ','Actualizaciones y consultas de rangos',['usaco-gold-purs','usaco-plat-segtree-ext'],['Derivar dos Fenwick para sumas de rango','Componer etiquetas de propagación diferida'],[
{title:'Cambiar un intervalo completo',body:'Agregar x a cada valor de [l,r] mediante actualizaciones puntuales cuesta O((r−l+1)log n). Las estructuras de actualización por rango representan el efecto de forma compacta. Para suma con incrementos, puedes usar dos Fenwick basados en diferencias. Para operaciones más generales, un árbol de segmentos con propagación diferida guarda etiquetas pendientes y las empuja a sus hijos únicamente cuando necesita descender.'},
{title:'Derivar los dos Fenwick',body:'Con índices desde uno, sea D el arreglo de diferencias y a[i]=Σ_{j≤i}D[j]. Entonces prefijo(p)=Σ_{i≤p}a[i]=Σ_{j≤p}(p−j+1)D[j]=p·ΣD[j]−Σ(j−1)D[j]. Guarda D en B1 y (j−1)D[j] en B2. Para agregar x en [l,r], modifica D[l]+=x y D[r+1]−=x; actualiza ambos árboles con esos coeficientes. Una suma de intervalo sigue siendo prefijo(r)−prefijo(l−1).'},
{title:'Ejemplo y etiquetas',body:'Parte de [0,0,0,0,0] y agrega tres en [2,4]. Queda [0,3,3,3,0], cuyo prefijo hasta cuatro es nueve. En las diferencias aparece +3 en dos y −3 en cinco. Un árbol diferido almacenaría, para un intervalo de longitud len totalmente cubierto, suma+=3·len y etiqueta+=3. Antes de visitar hijos, aplica la etiqueta a ambos y límpiala. Si también hay asignaciones, una asignación posterior reemplaza etiquetas anteriores y el orden de composición debe especificarse cuidadosamente.'},
{title:'Costo y ejercicio de composición',body:'Ambas alternativas permiten operaciones O(log n) y memoria O(n) para este problema. Dos Fenwick son específicos de la estructura algebraica de suma y diferencias; no los sustituyas directamente por mínimo. En un árbol diferido, el agregado del nodo debe reflejar ya todas sus etiquetas aunque sus hijos no estén actualizados. Practica sobre [1,2,3]: asigna todo a cuatro y después suma dos al último elemento, obteniendo [4,4,6] y suma catorce. Invertir las operaciones produce doce; esa diferencia revela por qué las etiquetas no siempre conmutan.'}
],'Partiendo de ceros, agregar 3 a [2,4] produce ¿qué suma en [1,4]?',['3','6','9','12'],2,'Hay tres posiciones modificadas: 2,3,4. Cada una vale 3, así que suman 9.'),
P('sparse-segtree','Árboles de segmentos dispersos',['usaco-plat-segtree-ext'],['Crear nodos solo donde existen operaciones','Comparar dominio implícito y compresión'],[
{title:'Un universo enorme, pocas posiciones usadas',body:'Puedes necesitar consultas sobre posiciones entre cero y 10¹², pero recibir solo cien mil modificaciones. Reservar un arreglo para todo el universo no es viable. Un árbol de segmentos disperso conserva la partición por mitades del dominio, pero crea nodos únicamente cuando una operación los necesita. Un hijo ausente representa un intervalo completo en su estado inicial, que puede ser cero para sumas.'},
{title:'Seguir una actualización',body:'Sobre [0,16), agregar cinco en la posición trece visita [0,16), [8,16), [12,16), [12,14) y [13,14). Los otros intervalos pueden seguir sin nodo. Consultar [12,16) devuelve cinco y consultar [0,8) devuelve cero. El invariante de cada nodo existente es que su agregado coincide con todo su intervalo, incluyendo los valores iniciales de hijos ausentes. La ausencia representa información conocida, no una respuesta indefinida.'},
{title:'Diseñar la memoria',body:'Puedes representar nodos con índices de un vector que almacena hijo izquierdo, hijo derecho y agregado. Evita conservar referencias a elementos del vector mientras agregas nuevos nodos: una realocación puede invalidarlas. Para un dominio [L,R), usa medio=L+(R−L)/2 y detente cuando R−L=1. Las consultas deben devolver el valor neutro ante disjunción y no necesitan crear nodos. Si agregas propagación diferida, debes definir cómo heredan la etiqueta los hijos que aún no existían.'},
{title:'Costo y elección de técnica',body:'Con q actualizaciones puntuales y universo de tamaño U, el tiempo por operación es O(log U) y el máximo de nodos creados O(q log U), con posibles ahorros por caminos compartidos. Si conoces todas las coordenadas futuras, comprimirlas suele ser más sencillo y usa O(q) espacio. La compresión de puntos conserva orden, pero no longitudes: para medir segmentos debes guardar distancias originales. Practica actualizar posiciones tres y trece del ejemplo, consultar el total y dibujar qué nodos comparten ambos caminos. Comprueba que una consulta vacía no cree memoria innecesaria.'}
],'¿Qué representa normalmente un hijo ausente en un árbol disperso de sumas inicialmente cero?',['Un error de memoria','Un intervalo cuya suma es cero','Una suma desconocida'],1,'Todos sus puntos siguen en el estado inicial cero; por eso el intervalo puede responder sin crear nodos.'),
P('2DRQ','Consultas de rangos en dos dimensiones',['usaco-gold-purs','usaco-silver-more-prefix-sums'],['Extender prefijos y Fenwick a cuadrículas','Controlar la memoria de estructuras bidimensionales'],[
{title:'Rectángulos como combinación de prefijos',body:'En una cuadrícula, una consulta rectangular puede reconstruirse con cuatro prefijos. Define P(x,y) como la suma en filas hasta x y columnas hasta y. Para [x1,x2]×[y1,y2], suma P(x2,y2)−P(x1−1,y2)−P(x2,y1−1)+P(x1−1,y1−1). La última suma repone la esquina que se había restado dos veces. Si no hay actualizaciones, una tabla de prefijos resuelve cada consulta en tiempo constante.'},
{title:'Una matriz para verificar signos',body:'En la matriz de filas [1,2,3], [4,5,6], [7,8,9], el rectángulo de filas dos a tres y columnas dos a tres suma 5+6+8+9=28. Los prefijos necesarios son P(3,3)=45, P(1,3)=6, P(3,1)=12 y P(1,1)=1. Entonces 45−6−12+1=28. Este ejemplo también ayuda a detectar si intercambias filas y columnas o mezclas límites inclusivos y exclusivos.'},
{title:'Cambios puntuales con Fenwick 2D',body:'Para actualizar (x,y), recorre i=x,x+lowbit(x),… y, dentro de cada fila de Fenwick, j=y,y+lowbit(y),…; agrega delta a cada celda visitada. La consulta de prefijo realiza los dos recorridos descendentes. Cada celda representa el producto de dos intervalos de lowbit, por lo que la descomposición no superpone posiciones. Si las coordenadas son dispersas y conocidas antes, puedes construir listas comprimidas de y para cada nodo exterior, evitando una matriz de tamaño gigantesco.'},
{title:'Costo, alternativas y práctica',body:'Un Fenwick denso de N por M usa O(NM) espacio y O(log N·log M) por operación; no basta con comprimir x e y por separado si su producto todavía es enorme. Una estructura dispersa fuera de línea puede usar O(q log q) memoria y O(log²q) por operación, según la construcción. Para consultas estáticas, un barrido puede ser más sencillo. Practica agregar diez al centro de la matriz: el rectángulo del ejemplo debe pasar de 28 a 38. Verifica rectángulos de una celda y los que tocan las fronteras cero de los prefijos.'}
],'En la matriz 1..9 por filas, ¿cuánto suma el bloque inferior derecho 2×2?',['24','26','28','30'],2,'El bloque contiene 5,6,8,9 y su suma es 28; también 45−6−12+1=28.'),
P('DC-SRQ','Divide y vencerás para consultas estáticas',['usaco-gold-lca-euler','usaco-plat-segtree-ext'],['Responder operaciones asociativas sin actualizaciones','Conservar el orden de combinaciones'],[
{title:'Asociatividad sin necesidad de inversos',body:'Una suma de rango puede resolverse restando prefijos porque la suma admite una operación inversa. Otras operaciones asociativas, como multiplicar matrices, no siempre permiten hacerlo. Divide y vencerás crea resúmenes que unen una parte izquierda y una derecha sin exigir inversos ni idempotencia. La entrada debe ser estática: si cambian elementos, los resúmenes precalculados pueden quedar obsoletos en muchos niveles.'},
{title:'Resolver los intervalos que cruzan el centro',body:'Divide un bloque [L,R] en medio M. Calcula sufijos A[l]⊗…⊗A[M] para cada l de la mitad izquierda y prefijos A[M+1]⊗…⊗A[r] para cada r de la derecha. Toda consulta con l≤M<r se responde combinando exactamente esos dos resúmenes. En [a,b,c,d], el rango [1,3] con índices desde cero cruza entre b y c: combinamos el sufijo b con el prefijo c⊗d, obteniendo b⊗c⊗d.'},
{title:'Fuera de línea y tabla disjunta',body:'Si todas las consultas están disponibles, responde las que cruzan el centro y reparte las demás recursivamente entre ambas mitades. Esto cuesta O((n+q)log n) con una implementación directa. Para responder consultas futuras, guarda resúmenes de cada nivel como una tabla dispersa disjunta. Con bloques alineados a potencias de dos, el bit más significativo de l XOR r identifica el nivel que separa sus extremos; allí los dos resúmenes no se superponen. Para l=r devuelve el elemento directamente.'},
{title:'Garantías y ejercicio',body:'La variante de tabla requiere O(n log n) tiempo y memoria de preparación, y O(1) por consulta si la operación y el cálculo del nivel cuestan constante. A diferencia de la tabla de mínimos con bloques solapados, sirve para cualquier operación asociativa de tamaño fijo. No inviertas el orden al construir sufijos: para matrices, A·B no suele ser B·A. Practica con concatenación como ejemplo visual, reconociendo que su costo real crece con la longitud; después usa matrices 2×2 para obtener agregados de tamaño constante y comprobar una consulta contra el producto directo.'}
],'¿Qué propiedad necesita la combinación de una tabla disjunta?',['Conmutatividad e inverso','Asociatividad','Idempotencia obligatoria'],1,'Los bloques son disjuntos y se combinan en orden. Asociatividad basta; no se requiere invertir ni repetir elementos.'),
P('sqrt','Descomposición en bloques y algoritmo de Mo',['usaco-gold-purs','usaco-silver-sorting-custom'],['Equilibrar trabajo por bloque y fronteras','Ordenar consultas para reutilizar una ventana'],[
{title:'Un punto intermedio útil',body:'La descomposición por raíz cuadrada divide n posiciones en bloques de tamaño B. Una consulta recorre a mano las fronteras parciales y usa resúmenes para los bloques completos. Una actualización puntual cambia el valor y ajusta el resumen de su bloque. Esta idea resulta útil cuando combinar todo en un árbol es complicado o cuando las operaciones admiten un mantenimiento sencillo por bloques.'},
{title:'Elegir el tamaño con una cuenta',body:'Para sumas, una consulta visita O(B+n/B) datos resumidos o individuales. El equilibrio se alcanza cerca de B=√n. Con n=100 y B=10, un rango puede requerir revisar hasta dieciocho posiciones fronterizas y alrededor de diez sumas de bloque. No es una prueba de que siempre sea más rápido que Fenwick, pero ofrece una implementación flexible. Si actualizar un bloque cuesta B, debes incluir también esa carga al decidir su tamaño.'},
{title:'Mo para frecuencias difíciles',body:'El algoritmo de Mo procesa consultas estáticas de intervalos en un orden que reduce el movimiento de sus extremos. Ordena por bloque de la izquierda y, dentro de cada bloque, por derecha; alternar el sentido de la derecha suele mejorar constantes. Mantén una ventana [l,r] y funciones agregar y quitar un elemento. Para contar valores distintos, incrementa frecuencias al agregar y modifica el total solo al pasar entre frecuencia cero y uno.'},
{title:'Costo y condiciones',body:'Con tamaño B, el movimiento típico de Mo está acotado por O(n²/B+qB), más ordenar consultas, suponiendo cambios O(1). Con q del orden de n y B≈√n da O((n+q)√n). Es una técnica fuera de línea: no sirve directamente si la siguiente consulta depende de una respuesta previa que aún no conoces, ni maneja cambios de valores sin extensiones. Practica consultas [0,2], [1,3], [0,3] en [1,2,1,3]: hay 2,3,3 valores distintos. Dibuja cada movimiento y comprueba que quitar una copia no elimina un valor todavía presente.'}
],'En [1,2,1,3], ¿cuántos valores distintos tiene el rango [1,3] desde cero?',['2','3','4'],1,'El rango contiene [2,1,3], tres valores distintos.'),
P('binary-jump','Saltos binarios y ancestros',['usaco-silver-intro-tree','usaco-silver-func-graphs'],['Precalcular saltos de potencias de dos','Resolver ancestros y LCA'],[
{title:'Saltar muchas veces con pocos pasos',body:'Si cada vértice tiene un sucesor, podemos precalcular a dónde llega después de 1,2,4,8,… saltos. Define up[k][v] como el resultado de aplicar el sucesor 2^k veces desde v. La recurrencia es up[k][v]=up[k−1][up[k−1][v]]. Esto funciona en árboles enraizados usando el padre como sucesor y también en grafos funcionales, aunque estos contengan ciclos.'},
{title:'Descomponer una distancia',body:'Para subir trece niveles, escribe 13=8+4+1 y aplica los tres saltos correspondientes. En una cadena 0←1←2←3←4←5, el tercer ancestro de cinco es dos: un salto de dos lleva a tres y uno más a dos. Si haces que el padre de la raíz sea ella misma, cualquier salto excesivo permanece en la raíz; si el problema exige indicar inexistencia, debes comprobar antes la profundidad o usar un centinela seguro.'},
{title:'LCA con dos vértices',body:'Primero iguala profundidades subiendo al más profundo. Si ambos vértices coinciden, ya tienes el ancestro común. Si no, examina potencias de mayor a menor y sube ambos cuando sus ancestros a esa potencia sean diferentes. El invariante mantiene a los vértices por debajo del LCA y evita saltar por encima de él. Al terminar, sus padres coinciden y ese padre es la respuesta. También puedes guardar agregados sobre cada salto, como el máximo peso recorrido.'},
{title:'Dimensión correcta y práctica',body:'Para árboles de n vértices, preprocesar hasta log₂n niveles cuesta O(n log n) tiempo y memoria; cada consulta cuesta O(log n). Para un grafo funcional con consultas de k hasta 10¹⁸, necesitas cerca de sesenta niveles, aunque n sea pequeño. No dimensionar según el máximo salto es un error frecuente. Practica un ciclo 0→1→2→0: después de ocho saltos desde cero llegas a dos, porque 8 mod 3=2. Verifica que la tabla reproduzca ese resultado y después agrega una cadena que desemboca en el ciclo.'}
],'¿Qué saltos representan trece en descomposición binaria?',['8,4,1','8,3,2','4,4,4,1','16,−3'],0,'13 en binario es 1101, por lo que se usan los niveles de 8,4 y 1 pasos.'),
P('merging','Fusionar de pequeño a grande',['usaco-gold-dp-trees','usaco-gold-intro-sorted-sets'],['Amortizar movimientos entre contenedores','Contar información por subárbol'],[
{title:'Unir bolsas sin copiarlo todo repetidamente',body:'Para conocer los colores distintos de cada subárbol, podrías mantener un conjunto y unir los de todos sus hijos. Si siempre copias el conjunto grande dentro de uno pequeño, una cadena de fusiones puede realizar trabajo cuadrático. La estrategia de pequeño a grande conserva el contenedor mayor y mueve hacia él los elementos del menor, intercambiando referencias o identificadores cuando conviene.'},
{title:'La idea de duplicación',body:'Primero imagina elementos únicos: si un elemento se mueve desde una bolsa de tamaño s hacia otra de tamaño al menos s, termina en una bolsa de tamaño al menos 2s. Su bolsa puede duplicarse solo O(log n) veces. Para colores con repeticiones, cada clave que no logra insertarse desaparece de la bolsa menor y ya no vuelve a moverse como esa misma ocurrencia. El análisis se adapta cobrando las fusiones a ocurrencias o tamaños de subárbol, sin asumir falsamente que todas las claves siempre duplican el conjunto resultante.'},
{title:'Ejemplo de colores',body:'Una raíz roja tiene dos hijos cuyos subárboles contienen colores {rojo,azul,verde} y {azul,amarillo}. Conserva el conjunto de tres e inserta las dos claves del pequeño: el resultado es {rojo,azul,verde,amarillo}, cuatro colores. Después agrega el color de la raíz, que ya estaba. Guarda la respuesta de cada hijo antes de transferir su bolsa, porque el contenedor puede quedar compartido o reutilizado. Una variante conserva mapas de frecuencias para responder color más frecuente, con reglas adicionales para empates.'},
{title:'Costo y cuidado con la propiedad',body:'Usando conjuntos balanceados, la técnica clásica obtiene O(n log²n) tiempo y O(n) almacenamiento de datos activos si transfieres y liberas bolsas correctamente. Con tablas hash el costo esperado puede bajar, pero no ofrece la misma garantía. Copiar una estructura completa al hacer swap anula la intención: intercambia contenedores con operaciones eficientes. Practica un árbol en forma de cadena y otro en estrella, contando cuántas inserciones realizas. Explica por qué ordenar hijos por tamaño no sustituye por sí solo conservar y reutilizar la bolsa mayor.'}
],'Al combinar conjuntos de tamaños 3 y 20, ¿qué haces?',['Insertar los 20 elementos en el de 3','Insertar los 3 elementos en el de 20','Copiar ambos a dos conjuntos nuevos'],1,'Mover el contenedor menor hacia el mayor limita la cantidad de veces que sus elementos participan en fusiones costosas.'),
P('hld','Descomposición pesada y ligera',['usaco-gold-tree-euler','usaco-plat-segtree-ext'],['Partir caminos de árbol en pocos intervalos','Responder consultas y cambios sobre rutas'],[
{title:'Subárboles son intervalos, caminos todavía no',body:'El orden de entrada DFS convierte subárboles en intervalos, pero un camino entre dos vértices puede atravesar varias ramas. La descomposición pesada y ligera, HLD, elige para cada vértice un hijo de mayor tamaño como pesado. Las aristas hacia los otros hijos son ligeras. Recorriendo primero al hijo pesado, cada cadena de aristas pesadas ocupa un intervalo continuo en un arreglo.'},
{title:'Por qué hay pocas cadenas',body:'Al bajar por una arista ligera, el subárbol elegido tiene a lo sumo la mitad del tamaño del subárbol actual: si fuera mayor, no podría existir otro hijo al menos igual de grande elegido como pesado. Por tanto, un camino desde la raíz cruza O(log n) aristas ligeras. Un camino entre dos vértices se descompone en O(log n) segmentos de cadenas. Esta es la garantía estructural que hace útil HLD; no depende de que el árbol esté balanceado.'},
{title:'Una consulta entre dos extremos',body:'Guarda head[v], cabeza de la cadena, y pos[v], posición en el arreglo. Mientras las cabezas de u y v sean distintas, procesa el segmento desde la cabeza más profunda hasta su extremo y reemplaza ese extremo por el padre de su cabeza. Cuando comparten cadena, consulta el segmento entre ambas posiciones. En un camino 0–1–2–3–4, todo puede ser una sola cadena y la consulta de uno a cuatro se vuelve un intervalo de cuatro valores. Para datos en aristas, guarda cada arista en el hijo y excluye el LCA de la última consulta.'},
{title:'Costo y orden de resultados',body:'Con un árbol de segmentos, una consulta de camino cuesta O(log²n), una actualización puntual O(log n) y el preprocesamiento O(n). La memoria es O(n). Sumas y máximos permiten combinar segmentos sin preocuparse por dirección, pero funciones o cadenas no conmutativas requieren conservar el orden de recorrido y posiblemente resúmenes invertidos. Practica un árbol con raíz y dos cadenas de tres vértices: dibuja los intervalos que atraviesa la ruta entre sus hojas. Comprueba por separado consultas de un vértice consigo mismo y caminos donde un extremo es ancestro del otro.'}
],'¿Qué garantiza que haya O(log n) aristas ligeras en un camino hacia la raíz?',['Todos los vértices tienen dos hijos','El tamaño del subárbol al bajar por una ligera se reduce al menos a la mitad','Las cadenas tienen longitud fija'],1,'Una sucesión de reducciones por factor dos solo puede ocurrir O(log n) veces antes de llegar a tamaño uno.'),
P('centroid','Descomposición por centroides',['usaco-gold-dp-trees','usaco-plat-binary-jump'],['Dividir un árbol en componentes equilibradas','Mantener distancias a vértices activados'],[
{title:'Separar por tamaño, no por profundidad',body:'Un centroide de un árbol es un vértice cuya eliminación deja componentes de tamaño a lo sumo n/2. No es necesariamente el centro según distancias. Para encontrarlo, calcula tamaños y desplázate hacia una componente con más de la mitad si existe. Elimina conceptualmente el centroide y repite en cada componente. El árbol de esta descomposición tiene profundidad O(log n) porque los tamaños se reducen al menos a la mitad.'},
{title:'El caso de una cadena',body:'En el camino de siete vértices 0–1–2–3–4–5–6, el vértice tres es un centroide. Al quitarlo quedan dos componentes de tres; uno y cinco pueden ser sus centroides. Si activas el vértice seis, registra para cada ancestro de seis en la descomposición la distancia desde ese centroide hasta seis. Una consulta desde cero considera dist(0,c)+mejor[c] para sus ancestros centroides. El centroide tres produce 3+3=6, que es la distancia correcta.'},
{title:'Por qué aparece una respuesta exacta',body:'Para cualquier vértice activado r y consulta v, hay un primer centroide que separa sus componentes, o coincide con uno de ellos. Ese centroide pertenece al camino original entre v y r, así que dist(v,r)=dist(v,c)+dist(c,r). Para otros centroides, la suma es una cota superior por desigualdad triangular. Guardar el mínimo de distancias de activados a cada centroide y minimizar las sumas encuentra una respuesta exacta. Esto supone distancias de árbol con aristas no negativas para la interpretación métrica.'},
{title:'Costo y variantes',body:'La construcción y el almacenamiento de distancias a ancestros centroides cuestan O(n log n). Con esas distancias precalculadas, activar y consultar cuestan O(log n); si calculas cada distancia con LCA durante cada operación, puede aparecer un factor logarítmico adicional. Mantener solo un mínimo permite activaciones, pero no desactivar correctamente el vértice que producía ese mínimo; para borrados necesitas multiconjuntos u otra estructura. Practica activar los extremos de la cadena: la consulta en tres debe devolver tres y en cinco debe devolver uno. Verifica también el caso sin vértices activos.'}
],'En una cadena de siete vértices, quitar el centroide central deja componentes de ¿qué tamaños?',['1 y 5','2 y 4','3 y 3'],2,'Quitar el vértice de índice 3 separa los índices 0,1,2 de 4,5,6; ambas componentes tienen tres vértices.'),
P('VT','Árboles virtuales para pocos vértices importantes',['usaco-gold-tree-euler','usaco-plat-binary-jump'],['Comprimir la estructura relevante de un árbol','Conservar ancestros y longitudes de caminos'],[
{title:'Muchas preguntas pequeñas en un árbol grande',body:'Imagina un árbol de doscientos mil vértices y una consulta que menciona solo diez. Recorrer todo el árbol para cada consulta desperdicia información irrelevante. Un árbol virtual conserva los vértices importantes y los ancestros comunes necesarios para describir cómo se conectan. Cada arista virtual puede representar una cadena de muchas aristas originales. La técnica sirve cuando esas cadenas se pueden resumir sin perder lo que la pregunta necesita.'},
{title:'Qué vértices agregar',body:'Ordena los k vértices importantes por tin de DFS. Agrega el LCA de cada pareja consecutiva en ese orden, ordena de nuevo y elimina duplicados. Esta colección contiene todos los puntos de ramificación necesarios y tiene a lo sumo 2k−1 vértices para k≥1. Con raíz cero, hijos uno y dos, y hojas tres y cuatro bajo uno, los importantes {3,4,2} necesitan agregar uno y cero: el árbol virtual tiene cinco vértices.'},
{title:'Conectar mediante una pila',body:'Recorre los vértices reunidos por orden de entrada. Mantén una pila de ancestros; retira los que ya no sean ancestros del siguiente vértice usando los tiempos tin y tout. El ancestro restante más profundo es su padre virtual. Una arista de padre p a v recibe longitud depth[v]−depth[p] en un árbol sin pesos, o la diferencia de distancias a la raíz si hay pesos. Ahora una DP sobre este árbol pequeño puede contar pares, sumar distancias o propagar marcas.'},
{title:'Costo y precauciones',body:'Con LCA en O(log n), construir una consulta cuesta O(k log k+k log n), además del preprocesamiento global; con LCA constante, domina O(k log k). El espacio de la consulta es O(k). No incluyas siempre la raíz original si no hace falta: basta el cierre por LCA, salvo que la pregunta la requiera. Si una cadena tiene restricciones internas que no se resumen en su longitud, debes conservar un agregado más rico. Practica importantes {3,4}: el árbol virtual debe tener tres vértices, con uno como raíz virtual, y mantener distancia dos entre las dos hojas.'}
],'Para k vértices importantes, ¿cuántos vértices puede tener su cierre virtual por LCA?',['A lo sumo k²','A lo sumo 2k−1','Siempre exactamente n'],1,'Agregar LCAs de consecutivos en orden DFS introduce como máximo k−1 vértices nuevos; al eliminar duplicados quedan a lo sumo 2k−1.'),
P('kruskal-tree','Árbol de reconstrucción de Kruskal',['usaco-gold-mst','usaco-plat-binary-jump'],['Registrar el momento en que se unen componentes','Contestar umbrales de conectividad con LCA'],[
{title:'Convertir la historia en un árbol',body:'Kruskal procesa aristas por peso creciente y fusiona componentes. En lugar de olvidar cada fusión, crea un nuevo nodo que tenga como hijos las raíces de las dos componentes unidas y etiqueta ese nodo con el peso de la arista. Los vértices originales quedan como hojas. El resultado representa una jerarquía de conectividad: cada nodo interno describe el primer umbral en que sus dos grupos quedaron conectados.'},
{title:'Un ejemplo de tres vértices',body:'Las aristas son 0–1 con peso dos, 1–2 con peso cinco y 0–2 con peso nueve. La primera fusión crea un nodo etiquetado dos con hojas cero y uno. La segunda crea otro etiquetado cinco que une esa componente con la hoja dos. La arista nueve se descarta porque sus extremos ya estaban conectados. El LCA de cero y dos es el nodo cinco: ese es el mínimo umbral T para conectarlos usando solo aristas de peso a lo sumo T.'},
{title:'Qué significa exactamente la respuesta',body:'Para dos hojas distintas, la etiqueta de su LCA es el mínimo, entre todos los caminos del grafo, del máximo peso de una arista del camino. No es la suma mínima de distancias ni el peso mínimo presente en la ruta. La prueba sigue la evolución de DSU: antes de esa fusión las hojas están separadas y después están juntas. Un grafo conectado con n vértices produce n−1 fusiones y 2n−1 nodos; uno desconectado produce un bosque.'},
{title:'Costo y detalles de implementación',body:'Ordenar aristas cuesta O(m log m), las fusiones usan DSU y preprocesar LCA sobre O(n) nodos cuesta O(n log n). Cada consulta puede costar O(log n) con saltos binarios u O(1) con Euler y RMQ. Mantén separada la raíz DSU de la raíz de reconstrucción para no confundir compresión de caminos con aristas históricas. Define la respuesta para u=v y para vértices desconectados según el enunciado. Practica aristas empatadas: el árbol binario puede cambiar con el desempate, pero las etiquetas que responden umbrales permanecen correctas.'}
],'Con aristas de pesos 2,5,9 del ejemplo, ¿cuál es el menor umbral para conectar 0 y 2?',['2','5','7','9'],1,'Con umbral 5 están disponibles 0–1 y 1–2. Con cualquier umbral menor, el vértice 2 sigue separado.'),
P('geo-pri','Geometría con vectores y productos cruzados',['usaco-bronze-rect-geo'],['Determinar orientación sin pendientes','Tratar colinealidad y overflow'],[
{title:'Puntos, desplazamientos y orientación',body:'Un punto (x,y) representa una posición; restar dos puntos produce un vector de desplazamiento. El producto punto ax·bx+ay·by mide proyección y ayuda a decidir ángulos. El producto cruzado bidimensional ax·by−ay·bx es un número con signo que indica orientación. Para tres puntos A,B,C, calcula cruz(B−A,C−A): positivo significa giro antihorario, negativo horario y cero colinealidad.'},
{title:'Un cálculo verificable',body:'Para A=(0,0), B=(4,0), C=(1,3), los vectores son (4,0) y (1,3). El cruzado vale 4·3−0·1=12, así que C está a la izquierda del segmento orientado A→B. El área del triángulo es |12|/2=6. Al intercambiar B y C cambia el signo, pero no el área. Esta fórmula funciona también con segmentos verticales y evita dividir entre una diferencia horizontal que podría ser cero.'},
{title:'Intersecciones y programa',body:'Dos segmentos propios se cruzan si los extremos de cada uno quedan en lados opuestos del otro. Para incluir toques y segmentos colineales, agrega una prueba de pertenencia: cruzado cero y coordenadas dentro de la caja del segmento. El programa calcula orientación y doble área para coordenadas entre −10⁸ y 10⁸; dentro de esa cota los productos intermedios caben en long long.',code:'#include <iostream>\n#include <cstdlib>\nusing namespace std;\nint main(){long long ax,ay,bx,by,cx,cy;cin>>ax>>ay>>bx>>by>>cx>>cy;long long z=(bx-ax)*(cy-ay)-(by-ay)*(cx-ax);cout<<(z>0?"ANTIHORARIO":z<0?"HORARIO":"COLINEAL")<<"\\n"<<llabs(z)<<"\\n";}'},
{title:'Precisión y práctica',body:'Orientación e intersección de dos segmentos cuestan O(1) tiempo y memoria, pero la representación numérica es parte de la corrección. Si las coordenadas llegan a 10⁹, la combinación de diferencias y restas puede exigir tipos más anchos; no multipliques primero en int para luego convertir. Con números reales necesitas una estrategia de tolerancias coherente con la escala. Practica puntos colineales (0,0),(2,2),(5,5) y segmentos que se tocan solo en un extremo. Explica qué cambia si el problema considera los extremos abiertos.'}
],'¿Cuál es el área del triángulo (0,0),(4,0),(1,3)?',['3','6','12','24'],1,'El producto cruzado tiene magnitud 12 y representa el doble del área; el área es 6.'),
P('sweep-line','Barrido geométrico y longitud cubierta',['usaco-plat-range-sweep','usaco-plat-rurq','usaco-plat-geo-pri'],['Medir la unión de rectángulos','Distinguir conteo activo de longitud geométrica'],[
{title:'Medir por franjas verticales',body:'Para calcular el área cubierta por muchos rectángulos alineados con los ejes, barre de izquierda a derecha. Entre dos coordenadas x consecutivas donde empieza o termina un rectángulo, el conjunto de intervalos verticales activos no cambia. El área de esa franja es ancho por longitud total de la unión vertical. El problema bidimensional se convierte en mantener la longitud cubierta de intervalos mientras se agregan y eliminan.'},
{title:'Un área con superposición',body:'Los rectángulos [0,3]×[0,2] y [2,5]×[1,3] tienen área seis cada uno. Su superposición mide uno por uno, así que la unión es once. El barrido produce franjas: de cero a dos, longitud cubierta dos y área cuatro; de dos a tres, longitud cubierta tres y área tres; de tres a cinco, longitud dos y área cuatro. La suma 4+3+4 confirma el resultado sin contar dos veces la región común.'},
{title:'El árbol guarda longitudes reales',body:'Comprime todas las coordenadas y, pero representa los intervalos entre coordenadas consecutivas, no solo los puntos. Cada nodo guarda un contador de cobertura y una longitud cubierta. Si su contador es positivo, todo su intervalo está cubierto y la longitud es yDerecha−yIzquierda. Si es cero, una hoja vale cero y un nodo interno suma las longitudes de sus hijos. Antes de aplicar eventos en x, agrega longitudActual·(x−xAnterior) al área y después procesa todos los eventos de esa misma x.'},
{title:'Costo y fronteras',body:'Hay dos eventos por rectángulo; ordenar y actualizarlos cuesta O(n log n) y O(n) memoria. La técnica descrita supone rectángulos con lados paralelos a los ejes y coordenadas ordenadas; descarta rectángulos de ancho o alto cero si no aportan área. Contar índices comprimidos en lugar de distancias reales da áreas equivocadas cuando los espacios son desiguales. Practica dos rectángulos idénticos: la unión debe tener el área de uno, aunque el contador llegue a dos. Después prueba rectángulos que solo comparten borde, cuyo solapamiento de área es cero.'}
],'¿Cuál es el área de unión de los dos rectángulos del ejemplo?',['10','11','12','13'],1,'Cada rectángulo tiene área 6 y la intersección área 1; 6+6−1=11.'),
P('convex-hull','Envolvente convexa de un conjunto de puntos',['usaco-plat-geo-pri','usaco-silver-sorting-custom'],['Construir el borde convexo por cadenas','Definir el tratamiento de puntos colineales'],[
{title:'La banda que rodea los puntos',body:'La envolvente convexa es el menor conjunto convexo que contiene todos los puntos: si tensaras una banda alrededor de clavijas, las esquinas tocadas formarían su frontera. Un punto interior no necesita aparecer como vértice del polígono. Esta estructura aparece en diámetros, separaciones y optimización geométrica. Antes de implementar, decide si la salida requiere solo esquinas o también todos los puntos situados sobre un borde.'},
{title:'Dos cadenas con una pila',body:'Ordena puntos por x y luego por y, y elimina duplicados. Recorre de izquierda a derecha para construir la cadena inferior: mientras los dos últimos puntos y el nuevo no formen el giro deseado, elimina el último. Después recorre en sentido inverso para la cadena superior. Con los cuatro puntos del cuadrado (0,0),(2,0),(2,2),(0,2) y el centro (1,1), el centro es retirado y quedan las cuatro esquinas.'},
{title:'La condición que conserva convexidad',body:'Si quieres solo vértices extremos, elimina mientras el cruzado sea menor o igual que cero al construir cadenas antihorarias. El caso cero elimina puntos intermedios de un mismo borde. Si necesitas conservarlos, cambia cuidadosamente a una comparación estricta y trata el caso de todos los puntos colineales para no duplicarlos al juntar cadenas. Cada eliminación descarta un punto que queda dentro del triángulo o sobre el segmento formado por sus vecinos relevantes, por lo que no puede ser una esquina necesaria.'},
{title:'Costo y pruebas',body:'Ordenar cuesta O(n log n) y cada punto entra y sale a lo sumo una vez de cada pila, así que la construcción posterior es O(n). El espacio es O(n). Usa aritmética suficientemente ancha para productos cruzados; la aparente simplicidad de la fórmula no evita overflow. Practica puntos (0,0),(1,0),(2,0): si piden solo esquinas, deben quedar los dos extremos, no un polígono de área positiva. Luego calcula el área de la envolvente del cuadrado mediante la fórmula del cordón y comprueba que sea cuatro.'}
],'Si solo se piden esquinas, ¿qué queda de (0,0),(1,0),(2,0)?',['Los tres puntos','Solo (1,0)','Los dos extremos'],2,'El punto central está en el segmento entre los extremos y no crea una esquina de la envolvente convexa.'),
P('convex-hull-trick','Optimizar DP con envolventes de rectas',['usaco-gold-intro-dp','usaco-plat-geo-pri'],['Reconocer transiciones como consultas a rectas','Comprobar monotonicidad de pendientes y consultas'],[
{title:'Separar lo que depende de cada índice',body:'Considera dp[i]=min_{j<i}(dp[j]+(x_i−x_j)²+C). Al expandir el cuadrado, dp[i]=x_i²+C+min_{j<i}((-2x_j)x_i+dp[j]+x_j²). Cada j aporta una recta con pendiente −2x_j e intercepto dp[j]+x_j²; cada i pregunta el mínimo en x_i. La transformación algebraica convierte muchas transiciones parecidas en consultas sobre una envolvente inferior de rectas.'},
{title:'Dos rectas y un punto de cambio',body:'Compara f(x)=2x+1 y g(x)=−x+10. Se cruzan en x=3: antes gana f y después gana g para minimizar. En x=2 los valores son cinco y ocho; en x=5 son once y cinco. La envolvente conserva únicamente rectas que son óptimas en alguna región. Una recta intermedia puede eliminarse si su intervalo de ventaja queda vacío; esa condición se comprueba comparando intersecciones, preferiblemente con productos cruzados seguros.'},
{title:'Cuándo sirve una deque',body:'La versión con deque exige un orden compatible: para mínimos, pendientes insertadas en orden decreciente y consultas x no decrecientes permiten avanzar el mejor candidato hacia adelante. La variante simétrica cambia signos u orden. Con x_i crecientes en la DP anterior, las pendientes −2x_j decrecen y las consultas crecen, por lo que encaja. Si solo las pendientes son monótonas, conserva la envolvente y busca por binaria cada consulta; no elimines candidatos por el frente ante consultas que podrían regresar a x menores. Las pendientes iguales requieren conservar únicamente el mejor intercepto.'},
{title:'Complejidad y verificación',body:'Con ambas monotonicidades, cada recta entra y sale una vez: O(n) tiempo después de cualquier ordenamiento necesario y O(n) memoria. Con consultas arbitrarias y pendientes ordenadas, una envolvente con búsqueda binaria admite O(log n) por consulta; para inserciones arbitrarias considera Li Chao o un contenedor de rectas. No ordenes estados de una DP si eso cambia qué transiciones j<i son válidas. Practica x=[0,2,5] y C=1 con dp[0]=0: dp[1]=5 y dp[2]=min(26,15)=15. Comprueba la respuesta evaluando las rectas antes de implementar la optimización.'}
],'¿Cuándo puede una deque descartar candidatos por el frente para consultas de mínimo?',['Siempre que las funciones sean rectas','Cuando pendientes y consultas siguen órdenes monótonos compatibles','Solo cuando todos los interceptos son cero'],1,'El avance irreversible del candidato óptimo exige que las consultas no regresen y que las rectas se inserten en un orden compatible de pendientes.'),
P('PIE','Principio de inclusión y exclusión',['usaco-gold-combo','usaco-silver-intro-bitwise'],['Corregir elementos contados varias veces','Enumerar intersecciones por subconjuntos'],[
{title:'Sumar conjuntos cuenta algunas cosas de más',body:'Si cuentas estudiantes que practican ajedrez y estudiantes que programan, quien hace ambas actividades aparece dos veces. La unión debe contar a cada persona una sola vez. Para dos conjuntos, |A∪B|=|A|+|B|−|A∩B|. Con tres, restamos intersecciones por pares y luego sumamos la triple, porque al restar pares eliminamos demasiadas veces los elementos presentes en los tres.'},
{title:'Múltiplos en un rango',body:'Entre uno y treinta, hay quince múltiplos de dos y diez de tres. Los múltiplos de ambos son múltiplos de seis, cinco números. La unión contiene 15+10−5=20. Si agregas múltiplos de cinco, suma seis, resta los múltiplos de diez y quince, y repón los de treinta: 15+10+6−5−3−2+1=22. El complemento contiene treinta menos veintidós, es decir ocho números no divisibles por dos, tres ni cinco.'},
{title:'La fórmula de subconjuntos',body:'Para k condiciones, recorre cada subconjunto no vacío S. Si |S| es impar, agrega la cantidad que cumple todas sus condiciones; si es par, réstala. Un objeto que pertenece a t conjuntos aporta Σ_{j=1..t}(−1)^(j+1)C(t,j)=1, por la expansión de (1−1)^t. Para divisibilidad, la intersección corresponde a múltiplos del mcm de los divisores elegidos, no siempre de su producto: el producto solo coincide cuando son coprimos.'},
{title:'Costo y seguridad numérica',body:'Una implementación directa cuesta O(k·2^k), más el costo de calcular las intersecciones, y requiere k pequeño. Si el mcm supera el límite N, la intersección aporta cero; puedes cortar antes de multiplicar para evitar overflow. Los signos afectan cantidades potencialmente grandes, así que usa un tipo con rango suficiente. Practica divisores cuatro y seis hasta veinticuatro: hay seis y cuatro múltiplos, con dos en común por mcm=12, así que la unión tiene ocho. Explica por qué usar 4·6=24 para la intersección daría una respuesta incorrecta.'}
],'¿Cuántos números de 1 a 30 son divisibles por 2 o por 3?',['15','20','25','30'],1,'Hay 15 múltiplos de 2, 10 de 3 y 5 de ambos; 15+10−5=20.'),
P('matrix-expo','Exponenciación de matrices y recurrencias',['usaco-gold-modular','usaco-gold-intro-dp'],['Representar una transición lineal','Aplicar muchas transiciones con cuadrados'],[
{title:'Una transición que se repite',body:'Una matriz describe cómo una lista de valores nuevos depende linealmente de la lista anterior. Si el mismo cambio se repite k veces, podemos elevar la matriz de transición a la potencia k mediante cuadrados, igual que una potencia modular de números. La multiplicación de matrices es asociativa, así que el procedimiento funciona aunque no sea conmutativa. La matriz identidad representa aplicar cero transiciones.'},
{title:'Fibonacci con dos componentes',body:'Guarda el vector columna [F(t+1),F(t)]. La siguiente pareja es [F(t+1)+F(t),F(t+1)], por lo que la transición es [[1,1],[1,0]]. Partiendo de [1,0], una aplicación produce [1,1], dos producen [2,1] y cinco producen [8,5]. Así, la entrada inferior de T^n·[1,0] es F(n). Para contar recorridos de longitud k en un grafo, la potencia de su matriz de adyacencia cuenta secuencias de aristas, permitiendo repetir vértices.'},
{title:'Programa completo',body:'El programa calcula F(n) módulo 1000000007, con F(0)=0. Multiplica matrices 2×2 y reduce durante cada acumulación para mantener productos dentro del rango de long long. Escribe primero la orientación del vector: usar filas en lugar de columnas cambia dónde colocas coeficientes. Para una recurrencia de orden d, conserva d valores consecutivos y construye una matriz d×d con una primera fila de coeficientes y desplazamientos en las restantes.',code:'#include <iostream>\n#include <array>\nusing namespace std;\nusing M=array<array<long long,2>,2>;const long long MOD=1000000007;\nM mul(M a,M b){M c{};for(int i=0;i<2;i++)for(int j=0;j<2;j++)for(int k=0;k<2;k++)c[i][j]=(c[i][j]+a[i][k]*b[k][j])%MOD;return c;}\nint main(){unsigned long long n;cin>>n;M r{{{1,0},{0,1}}},a{{{1,1},{1,0}}};while(n){if(n&1)r=mul(r,a);a=mul(a,a);n>>=1;}cout<<r[1][0]<<"\\n";}'},
{title:'Costo y alcance',body:'La multiplicación ordinaria de matrices d×d cuesta O(d³); elevar a k cuesta O(d³log k) y memoria O(d²). Es apropiado si d es pequeño y k enorme, no para una matriz densa de cientos de miles de vértices. La transición debe ser lineal y constante en el tiempo, salvo que modeles su variación explícitamente. Practica F(10)=55 y el caso n=0 para comprobar la identidad. Después agrega una componente constante uno para representar una recurrencia con término independiente y explica por qué permite seguir usando matrices.'}
],'¿Qué matriz representa cero aplicaciones de una transición?',['La matriz cero','La matriz identidad','La propia matriz de transición'],1,'La identidad deja cualquier vector igual, tal como repetir una operación cero veces.'),
P('bitsets','Bitsets y paralelismo por palabras',['usaco-silver-intro-bitwise','usaco-gold-knapsack'],['Procesar muchos booleanos con operaciones de bits','Reconocer límites de memoria y desplazamiento'],[
{title:'Muchos estados dentro de una palabra',body:'Un bitset representa una colección de valores booleanos como bits compactos. Operaciones como AND, OR y desplazamientos procesan bloques completos mediante instrucciones de máquina. Esto puede acelerar algoritmos que combinan conjuntos de estados del mismo modo. No elimina el número de estados matemáticos; reduce el trabajo por grupos de aproximadamente w bits, donde w suele ser el tamaño de palabra efectivo de la implementación.'},
{title:'Suma de subconjuntos con desplazamiento',body:'Sea posible[s] verdadero si alguna selección de objetos suma s. Al incorporar un objeto de peso x, las nuevas sumas son las anteriores desplazadas x posiciones, de modo que posible |= posible << x. Con pesos dos y tres, empezamos con {0}; después de dos tenemos {0,2}; después de tres, {0,2,3,5}. La operación usa el bitset anterior para el desplazamiento, por lo que cada objeto se incorpora una sola vez, como mochila 0/1.'},
{title:'Programa y aplicaciones',body:'El programa admite pesos no negativos y una consulta objetivo entre cero y cien mil. El tamaño de std::bitset es una constante de compilación; para límites dinámicos puedes implementar bloques de enteros o usar una biblioteca adecuada. También puedes representar los vecinos de cada vértice y contar vecinos comunes con (vecinos[u] & vecinos[v]).count(). Cada transformación debe conservar la correspondencia entre el índice del bit y el estado del problema.',code:'#include <iostream>\n#include <bitset>\nusing namespace std;\nint main(){const int LIMIT=100000;int n,target;cin>>n>>target;bitset<LIMIT+1>b;b[0]=1;while(n--){int x;cin>>x;if(x<0)return 0;b|=(b<<x);}if(target<0||target>LIMIT)return 0;cout<<(b[target]?"SI":"NO")<<"\\n";}'},
{title:'Complejidad y truncamiento',body:'Para n objetos y sumas hasta S, el modelo por palabras ofrece O(n·ceil(S/w)) operaciones y O(S) bits de memoria, con constantes dependientes de la biblioteca. Los bits que se desplazan más allá del tamaño se descartan. Con pesos no negativos, descartar sumas mayores que S es seguro si solo consultas hasta S; con pesos negativos, una suma grande podría volver a bajar y ese argumento falla. Practica pesos [2,2,3] y objetivo cuatro: es posible usando las dos copias de dos. Prueba también cero, que debe seguir alcanzable por la selección vacía.'}
],'Después de pesos 2 y 3, ¿qué conjunto de sumas es alcanzable?',['{0,2,3,5}','{2,3}','{0,1,2,3,4,5}'],0,'Cada peso se usa como máximo una vez: no tomar ninguno da 0, tomar uno da 2 o 3 y tomar ambos da 5.'),
P('DC-DP','Optimización de DP con divide y vencerás',['usaco-gold-dp-ranges','usaco-silver-prefix-sums'],['Probar monotonicidad del corte óptimo','Reducir candidatos por fila de DP'],[
{title:'Una recurrencia con muchos cortes',body:'Supón dp[g][i]=min_{g−1≤j<i}(dp[g−1][j]+C(j+1,i)): dividir los primeros i elementos en g grupos no vacíos. La implementación directa prueba O(n) cortes por estado y tarda O(gn²). Define opt[g][i] como un corte óptimo, usando siempre la misma regla para empates. La optimización exige demostrar opt[g][i]≤opt[g][i+1]. No es una propiedad automática de cualquier costo ni de toda programación dinámica.'},
{title:'Calcular el centro primero',body:'Para una fila g fija, resuelve primero la posición media m probando cortes dentro del rango candidato. Si su mejor corte es k, la monotonicidad garantiza que las posiciones a la izquierda no necesitan cortes mayores que k y las de la derecha no necesitan cortes menores que k. Recursa en ambos lados con esas fronteras. El estado conserva dos intervalos distintos: posiciones por calcular y candidatos permitidos para su óptimo; confundirlos provoca omisiones silenciosas.'},
{title:'Un costo con estructura',body:'Un ejemplo es C(l,r)=(suma de a[l..r])² con a no negativos. Para extremos ordenados, las sumas no negativas favorecen la desigualdad de Monge, una condición suficiente para monotonicidad de óptimos con desempate consistente. Con [1,2,3] y dos grupos, el corte después del primero cuesta 1²+5²=26, mientras cortar después del segundo cuesta 3²+3²=18. Los prefijos permiten evaluar cada costo en O(1). Si permites negativos, no reutilices la misma prueba sin revisarla.'},
{title:'Costo y validación',body:'Con costo O(1), cada fila se calcula en O(n log n), dando O(gn log n) tiempo y O(n) memoria si solo guardas dos filas. Mantén como imposibles los estados donde i<g y no sumes a infinito de forma que desborde. La condición de Monge puede expresarse C(a,c)+C(b,d)≤C(a,d)+C(b,c) para a≤b≤c≤d; debes justificarla para tu costo. Practica comparando la versión optimizada con la cuadrática en arreglos pequeños, y registra los cortes óptimos para detectar exactamente dónde fallaría una hipótesis de monotonicidad.'}
],'¿Qué condición permite limitar los cortes de la mitad izquierda al resolver el punto medio?',['Todos los costos son positivos','Los cortes óptimos son monótonos respecto al extremo derecho','El arreglo está ordenado por valor'],1,'Si opt[g][i]≤opt[g][m] para i<m, ningún óptimo de la izquierda necesita un corte mayor que el del punto medio.'),
P('dp-sos','DP sobre todos los submask: transformada SOS',['usaco-gold-dp-bitmasks'],['Agregar contribuciones de todos los subconjuntos','Evitar enumerar cada pareja máscara–submáscara'],[
{title:'Sumar sobre subconjuntos repetidamente',body:'Dado un valor f[mask] para cada subconjunto de k elementos, queremos F[mask]=Σ_{sub⊆mask}f[sub]. Enumerar todas las submáscaras de todas las máscaras cuesta O(3^k), porque cada elemento puede estar fuera de la máscara, dentro de la máscara pero fuera de la submáscara, o dentro de ambas. La DP SOS reutiliza sumas parciales procesando una dimensión binaria a la vez.'},
{title:'Un ejemplo con dos bits',body:'Con f[00]=1, f[01]=2, f[10]=3 y f[11]=4, las respuestas son F[00]=1, F[01]=3, F[10]=4 y F[11]=10. Copia f en F. Al procesar el bit cero, agrega F[mask sin bit] a F[mask] cuando ese bit está presente. Luego repite con el bit uno. Tras ambos pasos, F[11] reúne exactamente 1+2+3+4, mientras las máscaras más pequeñas incluyen solo sus propios subconjuntos.'},
{title:'El invariante por dimensiones',body:'Después de procesar los primeros b bits, F[mask] suma valores de máscaras que coinciden con mask en los bits todavía no procesados y pueden apagar libremente los bits ya procesados que están encendidos en mask. El siguiente bit divide estas posibilidades en dos grupos disjuntos: conservarlo o apagarlo. El programa calcula sumas exactas para hasta veinte bits, suponiendo que el resultado cabe en long long. Para sumar supermáscaras, invierte la dirección de la transición.',code:'#include <iostream>\n#include <vector>\nusing namespace std;\nint main(){int k;cin>>k;if(k<0||k>20)return 0;int n=1<<k;vector<long long>f(n);for(auto&x:f)cin>>x;for(int b=0;b<k;b++)for(int mask=0;mask<n;mask++)if(mask&(1<<b))f[mask]+=f[mask^(1<<b)];for(auto x:f)cout<<x<<" ";cout<<"\\n";}'},
{title:'Complejidad y no confundir operaciones',body:'Hay k pasadas sobre 2^k máscaras: O(k·2^k) tiempo y O(2^k) memoria. Cambiar suma por otra operación puede ser válido si el objetivo corresponde a esa agregación, pero invertir la transformada requiere propiedades adicionales; para sumas se resta en el paso inverso. Esta técnica no resuelve automáticamente una convolución XOR, que usa otra transformación. Practica frecuencias de conjuntos de habilidades: F[mask] cuenta estudiantes cuyas habilidades están contenidas en mask. Verifica que incluir la máscara vacía sea correcto según el significado del problema.'}
],'Con f=[1,2,3,4] para máscaras de dos bits, ¿cuánto vale F[11]?',['4','7','9','10'],3,'Las cuatro máscaras son subconjuntos de 11, por lo que F[11]=1+2+3+4=10.'),
P('plat-conclusion','Taller de cierre de Platino',['usaco-plat-hld','usaco-plat-convex-hull-trick','usaco-plat-dc-dp','usaco-plat-dp-sos'],['Combinar estructuras con pruebas de corrección','Reconocer las hipótesis de una optimización'],[
{title:'La dificultad está en la combinación',body:'En Platino, reconocer una estructura conocida rara vez basta. Puede ser necesario aplanar un árbol, ordenar eventos, mantener un agregado y responder una DP sobre esos resultados. Divide la solución en capas con responsabilidades claras: qué representa cada dato, qué consultas admite y por qué sus supuestos se cumplen. Una implementación elegante de la estructura equivocada sigue produciendo una respuesta equivocada.'},
{title:'Diagnóstico por ejemplos',body:'Si hay cambios de valores y sumas sobre caminos de un árbol fijo, HLD con árbol de segmentos es una combinación natural. Si solo se preguntan pequeños grupos de vértices en un árbol enorme, un árbol virtual evita recorrer lo irrelevante. Si una DP contiene min_j(m_j·x_i+b_j), estudia la envolvente de rectas, pero revisa el orden de pendientes y consultas. Para n=200000 y q=200000, un método cuadrático implicaría cuarenta mil millones de pasos, mientras unas pocas capas logarítmicas pueden ser viables.'},
{title:'Una prueba antes de cada optimización',body:'Escribe la versión sin optimizar y verifica que resuelva casos pequeños. Para cada aceleración, señala la propiedad utilizada: asociatividad, monotonicidad, independencia de subárboles, reducción de tamaño o una cota amortizada. Añade casos que ataquen esa propiedad, como pendientes iguales en CHT, valores negativos en búsquedas por prefijos, todos los puntos colineales en geometría y componentes desconectadas en Kruskal. Cuenta memoria además de tiempo; una tabla de estados puede exceder el límite aunque su número de operaciones parezca aceptable.'},
{title:'Un simulacro para avanzar',body:'Organiza un simulacro con tres problemas: consultas sobre árboles, DP optimizada y geometría o barrido. Dedica la primera parte a seleccionar un orden de resolución y obtener subtareas demostrables. Después del simulacro, escribe una explicación que otra persona pueda implementar sin ver tu código. Como comprobación conceptual, decide si puedes ordenar arbitrariamente los estados de una DP para hacer monótonas sus consultas: solo si pruebas que se conservan las dependencias. El siguiente nivel añade persistencia, flujos, algoritmos de cadenas y optimizaciones más especializadas; avanza conservando este hábito de probar cada condición.'}
],'¿Qué debes justificar antes de reordenar estados de una DP para usar CHT?',['Que los nombres de variables sean cortos','Que se conservan las dependencias y las transiciones permitidas','Que todos los valores caben en int'],1,'Reordenar puede permitir transiciones futuras o eliminar anteriores; conservar el problema original es parte indispensable de la prueba.'),
];
